frappe.ui.form.on('Workflow Task', {
    onload(frm) {
        //console.log('ONLOAD - Current doc:', frm.doc);
        
        // Проверяем корректные поля для перенаправления
        if (frm.doc.doc && frm.doc.wt_docname) {
            console.log('Redirecting to:', frm.doc.doc, 'with name:', frm.doc.wt_docname);
            
            //setTimeout(() => {
                // Перенаправляем на форму документа
                history.replaceState(null, null, frappe.router.make_url( frappe.get_prev_route() ) );
                frappe.set_route('form', frm.doc.doc.toLowerCase(), frm.doc.wt_docname);
            //}, 100); // Увеличиваем задержку для надёжности
        }
    }
});
